// The 1000 PUBLISHED TEST-SPLIT wavefronts, as their 33 Zernike coefficients.
// Recovered from phase_pool_cache_threeway.pth by least-squares projection onto
// PAPER_MODES; reconstruction error 7.4e-07 rad. synthPhase(coeffs) regenerates
// the exact published phase, so the demo runs on real test data, not resampled draws.
export const N_TEST_PHASES = 1000;
export const N_MODES = 33;
export const TEST_COEFFS_B64 = "";
export function testCoeffs(i){
  const bin=atob(TEST_COEFFS_B64), off=i*N_MODES*4;
  const buf=new ArrayBuffer(N_MODES*4), v=new DataView(buf);
  for(let k=0;k<N_MODES*4;k++) v.setUint8(k, bin.charCodeAt(off+k));
  const f=new Float32Array(buf), out=new Float64Array(N_MODES);
  for(let k=0;k<N_MODES;k++) out[k]=f[k];
  return out;
}
